package app.multimin.ui;
import javax.swing.*;import java.awt.*;import java.awt.image.*;import java.nio.file.*;import java.lang.reflect.*;
public class SettingsLayoutCheck {
 static JTabbedPane tabs(Container p){for(Component c:p.getComponents()){if(c instanceof JTabbedPane t)return t;if(c instanceof Container x){var found=tabs(x);if(found!=null)return found;}}return null;}
 static JButton button(Container p,String name){for(Component c:p.getComponents()){if(c instanceof JButton b&&name.equals(b.getText()))return b;if(c instanceof Container x){var found=button(x,name);if(found!=null)return found;}}return null;}
 static JComboBox<?> combo(Container p,String name){for(Component c:p.getComponents()){if(c instanceof JComboBox<?> b&&name.equals(b.getAccessibleContext().getAccessibleName()))return b;if(c instanceof Container x){var found=combo(x,name);if(found!=null)return found;}}return null;}
 static void documentContrast(Container p,Palette palette){for(Component c:p.getComponents()){if(c instanceof JTextPane text){Color color=javax.swing.text.StyleConstants.getForeground(text.getStyledDocument().getCharacterElement(0).getAttributes());if(Palette.contrastRatio(color,text.getBackground())<4.5)throw new AssertionError("Policy text lost contrast after theme change");}if(c instanceof Container child)documentContrast(child,palette);}}
 static Field field(String name)throws Exception{Field f=MainWindow.class.getDeclaredField(name);f.setAccessible(true);return f;}
 static JDialog dialog(){for(Window w:Window.getWindows())if(w instanceof JDialog d&&d.isShowing()&&d.getTitle().equals("Settings"))return d;throw new AssertionError("No settings dialog");}
 public static void main(String[] args)throws Exception{SwingUtilities.invokeAndWait(()->{try{UIManager.setLookAndFeel(UIManager.getCrossPlatformLookAndFeelClassName());System.setProperty("multimin.dev.gameCapture","true");MainWindow window=new MainWindow(new app.multimin.backend.PythonBridge());window.setVisible(true);String original=(String)field("swapKeyBinding").get(window);Method show=MainWindow.class.getDeclaredMethod("showMultitaskSettings");show.setAccessible(true);
  Timer first=new Timer(1000,e->{try{JDialog d=dialog();JTabbedPane pages=tabs(d);if(pages.getTabCount()!=4)throw new AssertionError("Missing settings pages");for(int i=0;i<4;i++){pages.setSelectedIndex(i);d.validate();if(i==3&&(!(pages.getComponentAt(i) instanceof JTabbedPane help)||help.getTabCount()!=6))throw new AssertionError("Missing Help/policy pages");BufferedImage image=new BufferedImage(d.getWidth(),d.getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();d.paint(g);g.dispose();javax.imageio.ImageIO.write(image,"png",Path.of("build/internal/settings-"+i+".png").toFile());}field("stagedSwapKeyBinding").set(window,"F6");if(!original.equals(field("swapKeyBinding").get(window)))throw new AssertionError("Unapplied hotkey changed");button(d,"Cancel").doClick();}catch(Exception error){error.printStackTrace();System.exit(1);}});first.setRepeats(false);first.start();show.invoke(window);if(!original.equals(field("swapKeyBinding").get(window)))throw new AssertionError("Cancel changed hotkey");
  Timer second=new Timer(1000,e->{try{JDialog d=dialog();field("stagedSwapKeyBinding").set(window,"F7");combo(d,"Theme").setSelectedItem("Light");button(d,"Apply").doClick();if(!window.uiPalette().text.equals(new Color(30,34,41)))throw new AssertionError("Light theme did not apply");if(!d.isShowing()||!"F7".equals(field("swapKeyBinding").get(window)))throw new AssertionError("Apply failed");if(!"F7".equals(new AppPreferences().getString("swapInputKey","")))throw new AssertionError("Applied hotkey was not persisted");documentContrast(d,window.uiPalette());JTabbedPane pages=tabs(d);pages.setSelectedIndex(3);d.validate();BufferedImage shot=new BufferedImage(d.getWidth(),d.getHeight(),BufferedImage.TYPE_INT_RGB);Graphics2D paint=shot.createGraphics();d.printAll(paint);paint.dispose();javax.imageio.ImageIO.write(shot,"png",Path.of("build/internal/settings-help-light.png").toFile());button(d,"OK").doClick();}catch(Exception error){error.printStackTrace();System.exit(1);}});second.setRepeats(false);second.start();show.invoke(window);System.out.println("PASS: four Settings pages, staged hotkey, Cancel, Apply stays open and OK closes");Method stop=MainWindow.class.getDeclaredMethod("shutdownServices");stop.setAccessible(true);stop.invoke(window);window.dispose();System.exit(0);
 }catch(Exception error){error.printStackTrace();System.exit(1);}});}
}
